        c.SetMinSum(initialMin);

        vm.prank(addr);
        (bool okPut, ) = address(c).call{value: putAmt}("");

        uint256 before = c.MinSum();

        vm.prank(addr);
        try c.Collect(collectAmt) {
        } catch {
        }

        assertTrue(c.MinSum() == before);
